(()=>{
let mode='stock',page=0,section;
const materials=[['PCB-A100','主控板','块','A.1'],['HSG-A100','铝制外壳','套','B.2'],['CON-D400','连接器','个','A.0']];
function rows(){return Array.from({length:mode==='stock'?12:18},(_,i)=>{const m=materials[i%3],n=i+1;return mode==='stock'?['华东库存组织',m[0],m[1],i%2?'WIP01':'RM01',m[3],'A-'+String(n).padStart(2,'0'),'LOT-202610'+(20+i%4)+'-'+String(n).padStart(3,'0'),(2100-i*40).toLocaleString()+' '+m[2],(21-i*.4).toFixed(1).replace('.0','')+' 箱',(1600-i*30).toLocaleString()+' '+m[2],(2000-i*40).toLocaleString()+' '+m[2]]:['INV-20261029-'+String(n).padStart(3,'0'),m[0]+' · '+m[1],['采购入库','生产领料','子库转移'][i%3],i%2?'WIP01':'RM01',i%2?'B-01-01':'A-01-01',(i%3===1?'-':'+')+(100+i*10),m[2],'2026-10-29 '+String(8+Math.floor(i/6)).padStart(2,'0')+':'+String(i%6*10).padStart(2,'0'),'已过账']})}
function render(){if(!section)return;const data=rows(),headers=mode==='stock'?['库存组织','物料编码','物料描述','子库','物料版本','货位','批次编码','主单位数量（单位）','辅助单位数量（单位）','主单位数量（单位）','主单位数量（单位）']:['交易编号','物料','交易类型','子库','货位','交易数量','单位','交易时间',''];section.innerHTML='<header><h2>业务概览</h2><button data-custom>☷ 自定义业务概览</button></header><div class="warehouse-overview-cards"><button data-mode="stock" aria-pressed="'+(mode==='stock')+'"><span>▣ 库存现有量及可用量</span><strong>12<small>种物料</small></strong><p>按子库、货位查看库存数量</p></button><button data-mode="transactions" aria-pressed="'+(mode==='transactions')+'"><span>▦ 今日库存交易</span><strong>18<small>笔</small></strong><p>华东库存组织 · 今日已过账交易</p></button></div><div class="warehouse-overview-table"><div class="warehouse-overview-scroll"><table><thead>'+(mode==='stock'?'<tr><th colspan="7">基本信息</th><th colspan="2">现有量</th><th>可预留量</th><th>可处理量</th></tr>':'')+'<tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+data.slice(page*6,page*6+6).map(r=>'<tr>'+r.map((v,i)=>'<td>'+(mode!=='stock'&&i===0?'<button class="warehouse-transaction-link">'+v+'</button>':escapeHTML(v))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><footer><span>共 '+data.length+' 条 · 第 '+(page+1)+' / '+Math.ceil(data.length/6)+' 页</span><button data-prev '+(!page?'disabled':'')+'>上一页</button><button data-next '+((page+1)*6>=data.length?'disabled':'')+'>下一页</button></footer></div>';section.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;page=0;render()});section.querySelector('[data-prev]').onclick=()=>{page--;render()};section.querySelector('[data-next]').onclick=()=>{page++;render()};section.querySelector('[data-custom]').onclick=custom;section.querySelectorAll('.warehouse-transaction-link').forEach(b=>b.onclick=()=>{const d=document.createElement('dialog');d.className='custom-business-overview-dialog';const row=data.find(r=>r[0]===b.textContent);d.innerHTML='<h2>库存交易详情</h2>'+row.map((v,i)=>'<p><strong>'+headers[i]+'</strong>　'+escapeHTML(v)+'</p>').join('')+'<button>关闭</button>';document.body.append(d);d.querySelector('button').onclick=()=>d.remove();d.showModal()})}
function custom(){const d=document.createElement('dialog');d.className='custom-business-overview-dialog';d.innerHTML='<h2>定义业务概览</h2><p>描述你想关注的业务，查询后可添加为统计卡片。</p><label>业务查询<textarea placeholder="支持库存、采购订单、转库单和销售订单查询"></textarea></label><button data-query>查询</button><p role="status"></p><footer><button data-cancel>取消</button><button data-save disabled>确认加入业务概览</button></footer>';document.body.append(d);d.querySelector('[data-query]').onclick=()=>{if(!d.querySelector('textarea').value.trim())return;d.querySelector('[role=status]').textContent='查询完成：共 12 条库存记录';d.querySelector('[data-save]').disabled=false};d.querySelector('[data-cancel]').onclick=()=>d.remove();d.querySelector('[data-save]').onclick=()=>{const card=document.createElement('button');card.innerHTML='<span></span><strong>12<small>条</small></strong><p>自定义业务查询</p>';card.querySelector('span').textContent=d.querySelector('textarea').value;section.querySelector('.warehouse-overview-cards').append(card);d.remove()};d.showModal()}
function sync(){const tabs=document.getElementById('workspace-activity-tabs');if(!tabs)return;if(!section||!section.isConnected){section=document.createElement('section');section.id='warehouse-business-overview';tabs.after(section);render();new MutationObserver(sync).observe(tabs,{subtree:true,attributes:true,attributeFilter:['hidden','aria-selected']})}const show=sessionStorage.getItem('yunxu-role')==='purchase-lead'&&!tabs.hidden&&tabs.querySelector('[data-tab="business"]')?.getAttribute('aria-selected')==='true';section.hidden=!show;if(show){document.getElementById('stats').hidden=true;document.getElementById('concerns').hidden=true;document.querySelector('main>.titleline').hidden=true;document.getElementById('inventory-balance-report')?.setAttribute('hidden','')}}
const base=openActivityBoard;openActivityBoard=function(){const result=base.apply(this,arguments);sync();return result};
})();
